#!/usr/bin/env bash
# Full local stack against a MOCK FACEIT API (simulated test world) for E2E tests and UI review.
# Never use for real analysis: all players/matches here are generated by backend/tests/support/world.py.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
DATA="${MOCK_DATA_DIR:-$(mktemp -d)}"
cd "$ROOT/backend"
uv run python -m tests.support.mock_faceit --port 8901 &
MOCK=$!
trap 'kill $MOCK 2>/dev/null' EXIT
FACEIT_API_BASE=http://127.0.0.1:8901/data/v4 FACEIT_API_KEY=test-key FACEIT_REQUESTS_PER_SECOND=50 \
AUTH_DEV_LOGIN=true DATA_DIR="$DATA" APP_BASE_URL=http://localhost:8000 \
uv run uvicorn app.main:app --port 8000
